def _reorient(self, from_node):
    """Return a copy of this subtree re-rooted at from_node.

    Assumes from_node exists somewhere in this subtree.
    """
    path = [self]
    node = self
    while node.label != from_node:
        for child in node.children:
            if child._find(from_node) is not None:
                node = child
                path.append(node)
                break
        else:
            raise ValueError("Tree could not be reoriented")
    result = path[-1]._copy()
    for parent, child in zip(reversed(path[:-1]), reversed(path[1:])):
        others = [c._copy() for c in parent.children if c is not child]
        result = Tree(parent.label, others + [result])
    return result

def build(i):
    node = path[i]
    if i < len(path) - 1:
        next_on_path = path[i + 1]
        children = [c._copy() for c in node.children if c is not next_on_path]
    else:
        children = [c._copy() for c in node.children]
    if i > 0:
        children.append(build(i - 1))
    return Tree(node.label, children)

